import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { getIdOrStringAccessor } from './column-utils.js';
import {
  DATA_TABLE_ACTION_COLUMN_ID,
  DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SUB_ROW_TRIGGER_ID,
} from '../DataTable/constants.js';
import { ColumnMinInstance } from '../types/internal-table-types.js';
import { ColumnGroup, TableColumn } from '../types/shared-table-types.js';

