/**
 * Extracts the column order from the column definition
 * @param columns - original columns from column definition
 *
 * @returns the column order
 */
function extractColumnOrder(columns: TableColumn[]): string[] {
  const columnOrder: string[] = [];
  for (const column of columns) {
    const parentColumn = column as ColumnGroup;
    if (parentColumn.columns) {
      for (const subColumn of parentColumn.columns) {
        columnOrder.push(getIdOrStringAccessor(subColumn));
      }
    } else {
      columnOrder.push(getIdOrStringAccessor(column));
    }
  }
  return columnOrder;
}

/**
 * Checks whether ids in the column order matches ids from the column definition.
 * @param order - configured column order
 * @param extractedOrder - column order from the column definition
 *
 * @throws wrong ID
 */
function validateColumnOrderIds(order: string[], extractedOrder: string[]) {
  // Sort the arrays
  const sortedOrder = order.sort();
  const sortedExtractedOrder = extractedOrder.sort();

  // Compare the sorted arrays element by element
  for (const i in sortedOrder) {
    if (sortedOrder[i] !== sortedExtractedOrder[i]) {
      throw sortedOrder[i];
    }
  }
}

/**
 * Checks is the column order is valid
 * @param order - column order
 * @param columns - original columns from column definition
 *
 * @returns true if columm order is valid and false if not
 */
export function validateColumnOrder(
  order: string[] | undefined,
  columns: TableColumn[],
): boolean {
  if (order === undefined) {
    return false;
  }
  // if order is not defined or empty string
  if (order.length === 0) {
    // eslint-disable-next-line no-console
    console.warn('Configured column order can not be empty array.');
    return false;
  }
  const orderWithoutPrefix = [...order].filter(
    (id) =>
      id !== DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID &&
      id !== DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID &&
      id !== DATA_TABLE_ACTION_COLUMN_ID &&
      id !== DATA_TABLE_SUB_ROW_TRIGGER_ID,
  );

  // check if the defined column order contains all ids
  const existingColumnOrder = extractColumnOrder(columns);

  if (orderWithoutPrefix.length !== existingColumnOrder.length) {
    // eslint-disable-next-line no-console
    console.warn(
      'Configured column order is not valid. The length of the configured column order does not match length of the existing columns.',
    );
    return false;
  }

  try {
    // check if all ids in the defined column order are typed correctly
    validateColumnOrderIds(orderWithoutPrefix, existingColumnOrder);
  } catch (wrongId) {
    // eslint-disable-next-line no-console
    console.warn(
      // eslint-disable-next-line no-template-curly-in-string
      `Configured column order is not valid. ID: '${wrongId}' doesn't match any of existing column IDs.`,
    );
    return false;
  }

  // check if sub-columns in the defined column order are next to each other
  const allSubColumns: Array<string | undefined>[] = [];

  const containSubColumns = columns.some((column) => 'columns' in column);
  if (!containSubColumns) {
    return true;
  }

  for (const column of columns) {
    const parentColumn = column as ColumnGroup;
    if (parentColumn.columns) {
      allSubColumns.push(parentColumn.columns.map((sub) => sub.id));
    }
  }

  for (const subColumns of allSubColumns) {
    const isValidOrder = areSubColumnsConjoined(subColumns, order);

    if (!isValidOrder) {
      // eslint-disable-next-line no-console
      console.warn(
        'Configured column order is not valid. Subcolumns ids that belong to the same parent must be ordered next to each other.',
      );
      return false;
    }
  }

  return true;
}

/**
 * Checks are the sub-columns ids ordered next to each other.
 * @param subColumns - sub columns
 * @param columnOrder - column order
 *
 * @returns true if the sub-columns ids are ordered next to each other, false otherwise
 */
function areSubColumnsConjoined(
  subColumns: (string | undefined)[],
  columnOrder: string[],
): boolean {
  const indices = subColumns
    .map((subColumn) => columnOrder.findIndex((colID) => colID === subColumn))
    .filter((id) => id >= 0)
    .sort();

  for (let i = 0; i < indices.length - 1; i++) {
    if (indices[i] + 1 !== indices[i + 1]) {
      return false;
    }
  }
  return true;
}

/**
 * Removes the affix columns from the columns list. The term 'affix' is reffering to both prefix and sufix columns.
 * @param columns - visible columns
 *
 * @returns columns without the custom columns
 */
export function removeAffixColumnsFromColumnOrder(
  columns: ColumnMinInstance[],
) {
  return [...columns].filter(
    (column) =>
      column.id !== DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID &&
      column.id !== DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID &&
      column.id !== DATA_TABLE_ACTION_COLUMN_ID &&
      column.id !== DATA_TABLE_SUB_ROW_TRIGGER_ID,
  );
}

/**
 * Changes the order of the columns.
 * @param direction - direction of moving
 * @param currentIndex - current position of the column
 * @param column - column that will be moved
 * @param columns - displayed columns
 *
 * @returns reordered columns
 */
export function changeColumnOrder(
  direction: 'left' | 'right',
  currentIndex: number,
  column?: ColumnMinInstance,
  columns?: ColumnMinInstance[],
): ColumnMinInstance[] | undefined {
  if (
    columns === undefined ||
    column === undefined ||
    (currentIndex - 1 < 0 && direction === 'left') ||
    (currentIndex + 1 >= columns.length && direction !== 'left')
  ) {
    return columns;
  }
  const orderedColumns = [...columns];
  const isParent = !!column.columns;

  const moveToLeft = direction === 'left';

  const newIndex = moveToLeft ? currentIndex - 1 : currentIndex + 1;
  const nextColumn = columns && columns[newIndex];

  const isNextColumnSubColumn =
    nextColumn.parent && !isParent && !column.parent ? true : false;

  const neighborOfGroupedColumn = moveToLeft
    ? columns[currentIndex - 1]
    : column.columns && columns[currentIndex + column.columns.length];

  const isNextAlsoGroupedColumn =
    isParent &&
    neighborOfGroupedColumn?.parent &&
    column.id !== neighborOfGroupedColumn?.parent?.id;

  // check if column that needs to be moved is parent column or column that needs to be replaced with is a sub-column
  if (isParent || isNextColumnSubColumn) {
    let currentIndexAdapted = currentIndex;

    const subColumnsLength = nextColumn?.parent?.columns?.length;
    if (isNextColumnSubColumn) {
      currentIndexAdapted =
        moveToLeft && subColumnsLength
          ? newIndex - (subColumnsLength - 1)
          : newIndex;
    }
    // extracts sub-columns that should be moved
    const subColumnsToBeMoved = orderedColumns?.splice(
      currentIndexAdapted,
      isNextColumnSubColumn
        ? nextColumn?.parent?.columns?.length
        : column.columns && column.columns.length,
    );

    let newIndexAdapted = newIndex;
    if (neighborOfGroupedColumn?.parent?.columns?.length) {
      newIndexAdapted = isNextAlsoGroupedColumn
        ? moveToLeft
          ? currentIndex - neighborOfGroupedColumn?.parent?.columns?.length
          : currentIndex + neighborOfGroupedColumn?.parent?.columns?.length
        : newIndex;
    }

    orderedColumns.splice(
      isNextColumnSubColumn
        ? moveToLeft && subColumnsLength
          ? currentIndex - (subColumnsLength - 1)
          : currentIndex
        : newIndexAdapted,
      0,
      ...[...(subColumnsToBeMoved ?? [])],
    );
  } else {
    if (column && column.columns) {
      column.columns.findIndex((item) => item.id === column.id);
    }

    orderedColumns[currentIndex] = orderedColumns?.splice(
      newIndex,
      1,
      orderedColumns[currentIndex],
    )[0];
  }

  return orderedColumns;
}

/**
 * Checks if moving a column is possible and returns whether moving to
 * the right or to the left should be disabled.
 *
 * @param column - the column in question
 * @param orderedColumns - either all or all visible columns in the current order
 * @returns - disableMoveLeft, disableMoveRight
 */
export function getDisableMoveLeftAndRight(
  column: ColumnMinInstance,
  orderedColumns: ColumnMinInstance[],
) {
  // column ids of the columns necessary for checking whether moving is possible in the current order
  const filteredOrderedColumnIds: string[] = [];
  if (column.parent) {
    orderedColumns.forEach((col) => {
      const parentId = column.parent?.id;
      // gather only sub column ids from the current column's parent
      if (col.parent && col.parent.id === parentId) {
        filteredOrderedColumnIds.push(col.id);
      }
    });
  } else if (column.columns) {
    orderedColumns.forEach((col) => {
      const parentId = col.parent ? col.parent.id : undefined;
      const isColumnWithoutChildOrParent =
        col.parent === undefined && col.columns === undefined;
      // gather all top level column ids
      if (isColumnWithoutChildOrParent) {
        filteredOrderedColumnIds.push(col.id);
      } else if (parentId && !filteredOrderedColumnIds.includes(parentId)) {
        filteredOrderedColumnIds.push(parentId);
      }
    });
  } else {
    return {
      disableMoveLeft: orderedColumns[0].id === column.id,
      disableMoveRight:
        orderedColumns[orderedColumns.length - 1].id === column.id,
    };
  }

  return {
    disableMoveLeft: filteredOrderedColumnIds[0] === column.id,
    disableMoveRight:
      filteredOrderedColumnIds[filteredOrderedColumnIds.length - 1] ===
      column.id,
  };
}
